from pathlib import Path
import json
from release import PRODUCTION, ORIGIN, metadata, prepare
root=Path(__file__).parent/'dist'
nav=[('','首页'),('how-it-works','工作原理'),('data-factory','数据与知识工厂'),('research','实践与研究'),('contact','关于与合作')]
def visual():return '''<figure class="visual" aria-label="合成示例：原文中的15个工作日被误提取为15天，需要复核"><figcaption>一份采购资料 · 一个值得留下的修正</figcaption><div class="document"><span class="document-label">原始资料 / 第 4 行</span><p>交货时间为订单确认后<br><mark>15 个工作日。</mark></p><span class="doc-rule"></span><span class="doc-rule short"></span></div><div class="annotation"><span>质量检查</span><p><s>15 天</s> <b>→ 15 个工作日</b></p><small>保留原文单位，而不是猜测。</small></div><div class="visual-foot">合成示例 · 非实时运行 · 候选修改仍需独立验证</div></figure>'''
def cta():return '''<div class="wrap band"><div><span class="eyebrow">从具体问题开始</span><h2>从一个真实业务问题开始。</h2><p class="lead">先定义什么是好结果，再讨论如何让 AI 做到。</p></div><a class="btn" href="/contact/">讨论你的业务场景 <span>↗</span></a></div>'''
pages={}
pages['']=('为业务构建持续进化的 AI Harness','''<div class="wrap"><div class="hero"><div><span class="eyebrow">业务专属的 AI 执行系统</span><h1>为具体业务，<br><em>构建 AI 工作流。</em></h1><p class="lead">从一个具体任务开始，连接资料、工具与质量检查。把人工修正留下来，让下一版有据可改。</p><div class="actions"><a class="btn" href="/contact/">讨论你的业务场景 <span>↗</span></a><a class="textlink" href="/how-it-works/">了解工作原理 ↗</a></div><p class="micro" style="margin-top:35px">从业务出发，而非让业务迁就工具。</p></div>'''+visual()+'''</div><div class="strip"><div><b>业务适配</b>从任务与验收标准出发</div><div><b>评测驱动</b>用证据，而不是直觉改进</div><div><b>边界可控</b>保留人工判断与发布闸门</div></div></div><section class="wrap"><div class="sectionhead"><div><span class="eyebrow">从实际问题出发</span><h2>模型很强。<br>业务需要的不止是模型。</h2></div><p>模型之外，信息、工具、规则与评测共同决定 AI 能否把事情做好。</p></div><div class="cards"><div class="card"><span class="num">上下文</span><h3>换一批数据，结果就不稳定</h3><p>让数据来源、任务上下文与工具调用成为系统的一部分，而非临时拼接。</p></div><div class="card"><span class="num">质量</span><h3>流程能跑，质量却难验收</h3><p>将“做得好”转化为明确的业务约束、测试样本与复核标准。</p></div><div class="card"><span class="num">反馈</span><h3>同样的错误，反复人工修正</h3><p>把失败与反馈沉淀为候选改进，并在独立评测后决定是否采用。</p></div></div></section><section class="light"><div class="wrap split"><div><span class="eyebrow">执行与改进，分开设计</span><h2>一个环交付任务。<br>一个环，让系统进步。</h2><p class="lead">Harness 是围绕模型的执行系统：它决定 AI 使用什么信息和工具、怎样完成任务，以及如何判断结果是否合格。</p><div class="flow"><span>运行环</span><i>→</i><span>任务 / 执行 / 检查</span></div><div class="flow"><span>改进环</span><i>→</i><span>反馈 / 评测 / 审批</span></div><div class="actions"><a class="textlink" href="/how-it-works/">查看双闭环架构 ↗</a></div></div><div class="paperdemo"><div class="micro" style="color:#68775b">我们的设计原则</div><h3>每一次改进，都经过评估。<br>每一次发布，都有边界。</h3><div class="line"><span>候选版本</span><span>在隔离环境中试验</span></div><div class="line"><span>独立评测</span><span>检查改善，也检查退化</span></div><div class="line"><span>发布决策</span><span>按约定规则审批</span></div><div class="line"><span>上线之后</span><span>保留监测与回退路径</span></div></div></div></section><section class="wrap split"><div><span class="eyebrow">首个重点方向</span><h2>从复杂资料，<br>到可检验的数据资产。</h2><p class="lead">数据与知识工厂是我们的首个重点方向。将抽取、证据定位、质量检查与人工反馈连接成可追溯的工作流。</p><div class="actions"><a class="btn secondary" href="/data-factory/">探索合成任务演示 ↗</a></div></div><div class="box"><div class="demohead"><span class="micro">资料 → 结构化记录</span><span class="tag">合成示例</span></div><div class="result-row"><b>输入</b><span>采购规格说明 / 文档片段</span></div><div class="result-row"><b>处理</b><span>字段提取 → 来源关联 → 规则检查</span></div><div class="result-row"><b>输出</b><span class="good">可追溯记录 + 待复核问题</span></div><p>不把缺失信息猜成答案，不把演示结果当成客户成果。</p></div></section>''')
pages['how-it-works']=('工作原理','''<div class="wrap subhero"><span class="eyebrow">工作原理</span><h1>模型之外，<br>还有一整套工作要做好。</h1><p class="lead">模型负责推理，Harness 组织上下文、工具、约束与反馈。我们从业务验收标准出发，设计每一个环节。</p></div><section class="wrap two"><div class="box"><span class="eyebrow">运行环</span><h2>在边界内，完成任务。</h2><p>业务输入 → 上下文与工具 → 执行 → 质量检查 → 交付或人工复核。</p><ul><li>连接授权数据与工具，不默认获得所有权限。</li><li>保留来源、步骤与异常，允许在不确定时停止。</li><li>将无法可靠判断的结果送交人工，而非强行给出结论。</li></ul></div><div class="box"><span class="eyebrow">改进环</span><h2>用反馈，验证下一步。</h2><p>失败与反馈 → 候选改进 → 独立评测 → 发布决策 → 监测。</p><ul><li>在限定范围内调整提示、工具配置或工作流。</li><li>用独立样本检查改善与回归，不只看优化样本。</li><li>通过人工审批或预先约定的闸门，才进入正式版本。</li></ul></div></section><section class="light"><div class="wrap"><span class="eyebrow">系统的组成</span><h2>为业务补齐四个层次。</h2><div class="sysgrid"><div><h3>模型 · 推理能力</h3><p>选择与任务匹配的模型与推理预算。</p></div><div><h3>信息与工具 · 任务资源</h3><p>授权资料、来源证据与可用工具。</p></div><div><h3>流程与权限 · 执行边界</h3><p>执行步骤、权限范围与人工节点。</p></div><div><h3>评测与反馈 · 改进依据</h3><p>验收标准、失败分类与回归检查。</p></div></div><p class="lead">这是一种系统设计方法，不意味着所有业务都能自动优化，也不等于持续训练模型权重。</p></div></section><section class="wrap"><span class="eyebrow">试点交付方向</span><h2>可交付的，不只有一次回答。</h2><div class="steps"><div class="step"><h3>业务专属 Harness</h3><p>任务定义、数据与工具接入方案、权限及人工节点。</p></div><div class="step"><h3>可执行的质量标准</h3><p>代表性样本、评测维度、失败分类与回归检查方法。</p></div><div class="step"><h3>受控的版本改进机制</h3><p>候选与基线对比、独立验证、发布边界和回退方案。</p></div><div class="step"><h3>可追溯的运行记录</h3><p>将来源、版本、执行步骤与人工决策纳入试点设计。</p></div></div><p class="notice">以上是服务设计与试点交付方向。具体能力、接入方式和交付范围以场景评估与合作约定为准。</p></section>''')
pages['data-factory']=('数据与知识工厂','''<div class="wrap subhero"><span class="eyebrow">数据与知识工厂</span><h1>把资料变成数据。<br>把修正变成改进的依据。</h1><p class="lead">不只关注提取了多少字段，更关注它来自哪里、能否通过检查，以及下一版怎样避免同样的错误。</p></div><section class="wrap" style="padding-top:10px"><p class="notice">交互概念演示：以下资料、版本与检查结果全部为合成示例，非客户数据、非模型实时运行，也不代表实际质量提升。</p><div class="tabs" role="tablist" aria-label="演示步骤"><button role="tab" aria-selected="true" data-stage="0">01 原始提取</button><button role="tab" aria-selected="false" data-stage="1">02 质量检查</button><button role="tab" aria-selected="false" data-stage="2">03 候选改进</button></div><div class="two"><div class="box"><div class="demohead"><h3>输入资料</h3><span class="tag">合成资料 001</span></div><p class="source">[L1] 项目：样例设备采购<br>[L2] 订购数量为 20 台。<br>[L3] 单价为人民币 1,200 元，含税。<br>[L4] 交货时间为订单确认后 15 个工作日。<br>[L5] 运费由双方另行确认。</p><p class="micro">保留原文 · 对应证据</p></div><div class="box" id="demo-output" aria-live="polite"></div></div><div class="box" style="margin-top:24px"><span class="eyebrow">发布之前</span><h3>候选改进，不等于已经发布。</h3><p>该示例只展示一个已知错误如何进入改进流程。是否采用候选版本，还需要独立样本、回归检查和约定的发布决策。没有验证的数据，保持未知。</p></div></section>''')
pages['research']=('实践与研究','''<div class="wrap subhero"><span class="eyebrow">实践笔记</span><h1>让方法可讨论。<br>让改进有证据。</h1><p class="lead">这里记录我们的系统设计思路与演示方法。它们不是客户案例，也不是已完成的性能评测报告。</p></div><section class="wrap" style="padding-top:10px"><article class="article"><small>笔记 01</small><div><h3>为什么要把运行环和改进环分开？</h3><p>完成业务任务与修改系统配置，是两种风险不同的动作。将它们分开，才能明确谁能改、改什么、何时生效。</p><details open><summary>展开设计笔记</summary><p>运行环使用固定版本执行任务；改进环收集问题并提出候选。候选必须经过独立评测和发布闸门，不能凭一次成功自动改写生产流程。发布之后仍需监测，并保留回退版本。</p></details></div><span>↗</span></article><article class="article"><small>笔记 02</small><div><h3>数据工厂：先建立失败分类，再谈优化</h3><p>缺失信息、错误推断、单位转换和来源丢失，需要不同的检查方法。</p><details><summary>展开设计笔记</summary><p>对每个字段分别记录来源位置、提取值和验证状态。缺失不等于否定，不确定不等于错误。先确认失败类型，再决定通过规则、上下文补充、工具调整还是人工判断解决。</p></details></div><span>↗</span></article><article class="article"><small>笔记 03</small><div><h3>从候选版本到业务证据</h3><p>优化样本上的进步，不一定能迁移到下一批数据。回归检查和独立测试同样重要。</p><details><summary>展开设计笔记</summary><p>在试点中，我们建议分离开发样本与独立评测样本，并同时关注质量、成本、时延和人工复核负担。基线、样本分布与评测边界未建立前，不报告提升百分比。</p></details></div><span>↗</span></article><div class="notice">技术参考：<a class="textlink" href="https://github.com/rsi-gear/gear" target="_blank" rel="noopener noreferrer">GEAR 开源项目 ↗</a>。引用用于说明研究方向，不代表合作、背书或已完成的产品集成。</div></section>''')
pages['contact']=('关于与合作','''<div class="wrap subhero"><span class="eyebrow">关于与合作</span><h1>先聊聊，<br>你想解决哪件具体的事。</h1><p class="lead">HarnessLoop 聚焦业务适配的 AI 执行系统。我们希望与数据和知识密集型业务一起，把一个具体任务做成可检查、可改进的工作流。</p></div><section class="wrap two" style="padding-top:10px"><div><h2>先定义一个小而清晰的试点。</h2><div class="steps"><div class="step"><h3>场景诊断</h3><p>明确任务、瓶颈与风险边界。</p></div><div class="step"><h3>样本与基线</h3><p>用获授权、脱敏的代表性样本确定验收方式。</p></div><div class="step"><h3>定制试点</h3><p>构建最小工作流，核验质量与人工成本。</p></div><div class="step"><h3>接入与持续优化</h3><p>按验证结果决定范围、发布与后续迭代。</p></div></div></div><div class="box"><h3>整理你的场景简报</h3><p>本页仅在浏览器中生成简报，不发送、不保存。正式联系入口将在确认后接入。</p><form class="form" id="brief-form"><label>希望 AI 完成什么任务？<input name="task" required maxlength="200" placeholder="例如：从供应商资料提取采购字段"></label><label>当前最难的部分<textarea name="pain" required maxlength="800" placeholder="例如：格式不统一，人工核对重复"></textarea></label><label>什么结果才算合格？<textarea name="criteria" required maxlength="800" placeholder="例如：关键字段必须能定位到来源"></textarea></label><button class="btn" type="submit">生成本地简报 ↗</button></form><p class="micro">请勿填写患者信息、客户个人信息、密码或商业机密。</p><div id="brief-panel" class="hidden"><h3>简报已在本地生成，尚未发送</h3><pre class="brief" id="brief"></pre><button class="btn secondary" id="copy-brief" type="button">复制简报</button><p id="copy-status" role="status"></p></div></div></section>''')

pages['privacy']=('隐私说明','')  # Body is generated by release.privacy(); no duplicate copy here.
from en_content import pages as en_pages, cta as en_cta
import re
en_pages['']=(en_pages[''][0],re.sub(r'<div class="visual document-study".*?</div></div></div><div class="strip">',visual().replace('一份采购资料 · 一个值得留下的修正','A purchase specification. A correction worth keeping.').replace('原始资料 / 第 4 行','Source document / line 4').replace('交货时间为订单确认后','Delivery after order confirmation:').replace('15 个工作日。','15 business days.').replace('质量检查','Quality check').replace('15 天','15 days').replace('15 个工作日','15 business days').replace('保留原文单位，而不是猜测。','Keep the original unit. Do not guess.').replace('合成示例 · 非实时运行 · 候选修改仍需独立验证','Synthetic example · Not live · Candidate requires testing').replace('合成示例：原文中的15个工作日被误提取为15天，需要复核','Illustrative extraction error requiring review')+'</div><div class="strip">',en_pages[''][1],count=1))
