for lang, content in [('zh',pages),('en',en_pages)]:
 for slug,(title,body) in content.items():
  body=prepare(body,slug,lang=='en')
  base='/' if lang=='zh' else '/en/'
  def url(s):return '/zh/' if lang=='zh' and not s else base+(s+'/' if s else '')
  labels=['首页','工作原理','数据工厂','实践笔记','关于与合作'] if lang=='zh' else ['Home','Approach','Data factory','Notes','About & contact']
  links=''.join(f'<a href="{url(s)}"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for (s,_),label in zip(nav,labels))
  if lang=='en':body=body.replace('href="/contact/"','href="/en/contact/"').replace('href="/how-it-works/"','href="/en/how-it-works/"').replace('href="/data-factory/"','href="/en/data-factory/"')
  other=('/en/' if lang=='zh' else '/')+(slug+'/' if slug else '')
  if lang=='en' and not slug:other='/zh/'
  switch=f'<a class="language" href="{other}" data-language="{"en" if lang=="zh" else "zh"}" lang="{"en" if lang=="zh" else "zh-CN"}" aria-label="{"Switch to English" if lang=="zh" else "切换到中文"}">{"EN" if lang=="zh" else "中文"}</a>'
  desc,seo=metadata(lang,slug,title)
  robots='index,follow' if PRODUCTION else 'noindex,nofollow'
  html=f'''<!doctype html><html lang="{'zh-CN' if lang=='zh' else 'en'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | HarnessLoop</title><meta name="description" content="{desc}"><meta name="robots" content="{robots}">{seo}<meta name="generator" content="HarnessLoop static site"><meta name="theme-color" content="#f7f9fb"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script src="/assets/language.js"></script><script defer src="/assets/app.js"></script><script defer src="/assets/evolution.js"></script></head><body><a class="skip" href="#main">{'跳转到主要内容' if lang=='zh' else 'Skip to content'}</a><header><div class="wrap nav"><a class="brand" href="{url('')}" aria-label="HarnessLoop {'首页' if lang=='zh' else 'home'}"><span class="logo" aria-hidden="true"></span>HarnessLoop</a><nav class="navlinks" id="navigation" aria-label="{'主导航' if lang=='zh' else 'Main navigation'}">{links}</nav><div class="navtools">{switch}<button class="menu" aria-label="{'切换导航' if lang=='zh' else 'Toggle navigation'}" aria-expanded="false" aria-controls="navigation">{'菜单' if lang=='zh' else 'Menu'}</button></div></div></header><main id="main">{body}{(cta() if lang=='zh' else en_cta().replace('href="/contact/"','href="/en/contact/"')) if slug not in ['contact','privacy'] else ''}</main><footer><div class="wrap foot"><div>© 2026 HarnessLoop <span>{'为业务而构建。' if lang=='zh' else 'Built around your work.'}</span></div><div><a class="footer-email" href="mailto:contact@harnessloop.ai">contact@harnessloop.ai</a><br><a href="{url('faq')}">{'常见问题' if lang=='zh' else 'FAQ'}</a> · {'简报在本地生成' if lang=='zh' else 'Briefs are generated locally'} · <a href="{url('privacy')}">{'隐私说明' if lang=='zh' else 'Privacy'}</a></div></div></footer></body></html>'''
  html=html.replace(' <span>↗</span>','').replace('<span>↗</span>','').replace(' ↗','').replace('↗','')
  path=root/('en' if lang=='en' else ('zh' if not slug else ''))/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(html)
(root/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="12" fill="#f7f9fb"/><path d="M14 20h25a13 13 0 0 1 0 26H25a13 13 0 0 1 0-26M14 20v12m0-12h12" fill="none" stroke="#245de4" stroke-width="4"/></svg>')
